 const radios=document.querySelectorAll('input[name="timing_mode"]'),times=document.getElementById('custom-reel-times'); radios.forEach(r=>r.addEventListener('change',()=>times.hidden=document.querySelector('input[name="timing_mode"]:checked').value!=='custom'));
 const quantity=document.getElementById('credit-quantity'),total=document.getElementById('credit-total'),buy=document.getElementById('buy-reel-credits'),config=document.getElementById('reel-paddle-config'),message=document.getElementById('reel-payment-message'),quantityError=document.getElementById('credit-quantity-error'),minimum={{ $minimumPurchase }},checkoutConfigured=Boolean(config.dataset.token&&config.dataset.priceId); const syncTotal=()=>{const qty=Number(quantity.value),valid=Number.isInteger(qty)&&qty>=minimum&&qty<=365;total.textContent=valid?`$${qty}`:`$${minimum}`;quantityError.hidden=valid;buy.disabled=!checkoutConfigured||!valid};quantity?.addEventListener('input',syncTotal);quantity?.addEventListener('blur',()=>{if(Number(quantity.value)<minimum){quantity.value=minimum;syncTotal()}});syncTotal();
